-- =====================================================================
-- EYE Check — 002 Row Level Security policies
-- The backend uses the *user's* JWT for user-owned data so these policies
-- are enforced on every request (defence in depth). Privileged writes
-- (AI results, risk assessments, dataset, logs, settings) are only possible
-- with the service role, which never leaves the backend.
-- =====================================================================

create or replace function public.is_admin()
returns boolean language sql stable security definer set search_path = public as $$
  select exists (
    select 1 from public.profiles
     where id = auth.uid() and role = 'admin' and status = 'active'
  );
$$;

create or replace function public.is_active_user()
returns boolean language sql stable security definer set search_path = public as $$
  select exists (select 1 from public.profiles where id = auth.uid() and status = 'active');
$$;

create or replace function public.is_active_staff()
returns boolean language sql stable security definer set search_path = public as $$
  select exists (
    select 1 from public.profiles
     where id = auth.uid() and account_type = 'staff' and status = 'active'
  );
$$;

-- true when the patient (or "no patient") belongs to the current user
create or replace function public.owns_patient(p_patient uuid)
returns boolean language sql stable security definer set search_path = public as $$
  select p_patient is null
      or exists (select 1 from public.patients where id = p_patient and owner_id = auth.uid());
$$;

create or replace function public.owns_screening(p_screening uuid)
returns boolean language sql stable security definer set search_path = public as $$
  select exists (select 1 from public.screenings where id = p_screening and user_id = auth.uid());
$$;

-- Enable RLS everywhere
alter table public.profiles                 enable row level security;
alter table public.patients                 enable row level security;
alter table public.medical_histories        enable row level security;
alter table public.vision_tests             enable row level security;
alter table public.screenings               enable row level security;
alter table public.ai_predictions           enable row level security;
alter table public.risk_assessments         enable row level security;
alter table public.screening_images         enable row level security;
alter table public.dataset_images           enable row level security;
alter table public.consent_records          enable row level security;
alter table public.activity_logs            enable row level security;
alter table public.roboflow_projects        enable row level security;
alter table public.admin_settings           enable row level security;
alter table public.staff_registration_codes enable row level security;

-- Anonymous clients get nothing
revoke all on all tables in schema public from anon;

-- ---------------- profiles ----------------
create policy profiles_select on public.profiles for select to authenticated
  using (id = auth.uid() or public.is_admin());
create policy profiles_update_self on public.profiles for update to authenticated
  using (id = auth.uid()) with check (id = auth.uid());
-- no insert/delete policy: accounts are created/removed only by the backend (service role)
revoke update on public.profiles from authenticated;
grant update (full_name, birth_date, gender, position, workplace) on public.profiles to authenticated;

-- ---------------- patients (staff only) ----------------
create policy patients_select on public.patients for select to authenticated
  using (owner_id = auth.uid() or public.is_admin());
create policy patients_insert on public.patients for insert to authenticated
  with check (owner_id = auth.uid() and public.is_active_staff());
create policy patients_update on public.patients for update to authenticated
  using (owner_id = auth.uid()) with check (owner_id = auth.uid());
create policy patients_delete on public.patients for delete to authenticated
  using (owner_id = auth.uid());

-- ---------------- medical_histories ----------------
create policy mh_select on public.medical_histories for select to authenticated
  using (user_id = auth.uid() or public.is_admin());
create policy mh_insert on public.medical_histories for insert to authenticated
  with check (user_id = auth.uid() and public.is_active_user() and public.owns_patient(patient_id));
create policy mh_update on public.medical_histories for update to authenticated
  using (user_id = auth.uid()) with check (user_id = auth.uid() and public.owns_patient(patient_id));
create policy mh_delete on public.medical_histories for delete to authenticated
  using (user_id = auth.uid());

-- ---------------- vision_tests ----------------
create policy vt_select on public.vision_tests for select to authenticated
  using (user_id = auth.uid() or public.is_admin());
create policy vt_insert on public.vision_tests for insert to authenticated
  with check (user_id = auth.uid() and public.is_active_user() and public.owns_patient(patient_id));
create policy vt_delete on public.vision_tests for delete to authenticated
  using (user_id = auth.uid());

-- ---------------- screenings ----------------
create policy scr_select on public.screenings for select to authenticated
  using (user_id = auth.uid() or public.is_admin());
-- users may only create a *pending* screening; AI results are written by the backend
create policy scr_insert on public.screenings for insert to authenticated
  with check (
    user_id = auth.uid() and public.is_active_user() and public.owns_patient(patient_id)
    and ai_status = 'pending' and primary_finding is null and risk_level is null
  );
create policy scr_update on public.screenings for update to authenticated
  using (user_id = auth.uid()) with check (user_id = auth.uid());
create policy scr_delete on public.screenings for delete to authenticated
  using (user_id = auth.uid());
revoke update on public.screenings from authenticated;
grant update (is_saved, saved_at) on public.screenings to authenticated;

-- ---------------- ai_predictions / risk_assessments (read-only for users) ----------------
create policy pred_select on public.ai_predictions for select to authenticated
  using (public.owns_screening(screening_id) or public.is_admin());
create policy risk_select on public.risk_assessments for select to authenticated
  using (public.owns_screening(screening_id) or public.is_admin());

-- ---------------- screening_images ----------------
create policy simg_select on public.screening_images for select to authenticated
  using (public.owns_screening(screening_id) or public.is_admin());
create policy simg_insert on public.screening_images for insert to authenticated
  with check (public.owns_screening(screening_id));

-- ---------------- consent_records ----------------
create policy consent_select on public.consent_records for select to authenticated
  using (user_id = auth.uid() or public.is_admin());
create policy consent_insert on public.consent_records for insert to authenticated
  with check (user_id = auth.uid() and public.owns_patient(patient_id));
create policy consent_update on public.consent_records for update to authenticated
  using (user_id = auth.uid()) with check (user_id = auth.uid());
revoke update on public.consent_records from authenticated;
grant update (consent_status, withdrawn_at) on public.consent_records to authenticated;

-- ---------------- admin-only tables (read for admins, writes via service role) ----------------
create policy ds_admin_select on public.dataset_images for select to authenticated using (public.is_admin());
create policy act_admin_select on public.activity_logs for select to authenticated using (public.is_admin());
create policy rf_admin_select on public.roboflow_projects for select to authenticated using (public.is_admin());
create policy settings_admin_select on public.admin_settings for select to authenticated using (public.is_admin());
-- staff_registration_codes: no policies at all → only the service role can read/write
